import { useEffect, useState } from "react";
import axios from "axios";
import { useAuth } from "../context/AuthContext";

export default function Dashboard() {
  const [units, setUnits] = useState([]);

  //const userInfo = JSON.parse(localStorage.getItem("userInfo"));
  //const token = userInfo?.token;
  
  const { user } = useAuth();
  const token = user?.token;


  useEffect(() => {
    const fetchUnits = async () => {
      try {
        const { data } = await axios.get(
          "http://localhost:5001/api/units"
        );
        setUnits(data);
      } catch (error) {
        console.error(error);
      }
    };

    fetchUnits();
  }, []);

  const handleBooking = async (id) => {
    try {
      await axios.post(
        "http://localhost:5001/api/bookings",
        {
          unitId: id,
          startDate: new Date(),
          endDate: new Date()
        },
        {
          headers: { Authorization: `Bearer ${token}` }
        }
      );

      alert("Booked!");
      window.location.reload();

    } catch (error) {
      alert("Booking failed");
    }
  };

return (
  <div style={{ padding: "30px", background: "#F3F4F6", minHeight: "100vh" }}>
    <h2 style={{ marginBottom: "20px" }}>Available Storage Units</h2>

    {units.length === 0 && <p>No units available.</p>}

    <div style={{
      display: "grid",
      gridTemplateColumns: "repeat(auto-fill, minmax(280px, 1fr))",
      gap: "20px"
    }}>
      {units.map((unit) => (
        <div
          key={unit._id}
          style={{
            background: "white",
            padding: "20px",
            borderRadius: "10px",
            boxShadow: "0 4px 10px rgba(0,0,0,0.1)"
          }}
        >
          <h3>{unit.name}</h3>
          <p><strong>Size:</strong> {unit.size}</p>
          <p><strong>Price:</strong> ${unit.pricePerDay}/day</p>

          <p>
            {unit.available ? "✅ Available" : "❌ Booked"}
          </p>

          {unit.available && (
            <button
              style={{
                marginTop: "10px",
                background: "#2563EB",
                color: "white",
                padding: "10px",
                border: "none",
                width: "100%",
                borderRadius: "6px"
              }}
              onClick={() => handleBooking(unit._id)}
            >
              Book Now
            </button>
          )}
        </div>
      ))}
    </div>
  </div>
);
}
